    e107: "Puha! (A کی طرف سے استعمال)",
    e108: "یہاں A وہی آواز (\"Puha!\") بطور بولنے والا اپنی جسمانی تھکاوٹ اور راحت بیان کرنے کے لیے استعمال کر رہا ہے۔",
    e109: "بولنے والا سوچنے کے وقفے کے دوران بات کی باری کھلی رکھنے کے لیے \"Øhm...\" استعمال کرتا ہے۔",
