    e1070: "\"Tusind tak for hjælpen!\" کا قدرتی جواب \"Det var så lidt!\" یا \"Selv tak!\" ہے۔",
    e1071: "7. سڑک پر اجنبی بمقابلہ دفتر میں ساتھی",
    e1072: "بمقابلہ اجنبی اور جان پہچان والے کے درمیان فرق",
    e1073: "بات شروع کرنے کے لیے \"Undskyld\" کب استعمال کیا جاتا ہے؟",
    e1074: "اجنبیوں سے بات \"Undskyld...\" سے شروع کی جاتی ہے، جبکہ جان پہچان کے لوگوں سے مسکرا کر براہِ راست پوچھا جاتا ہے: \"Må jeg lige forstyrre dig et øjeblik?\"۔",
    e1075: "8. دو طرح کے شائستہ انکار: کافی کی میز پر بمقابلہ صبح کی دوڑ",
    e1076: "اور دو مختلف انداز میں شائستہ انکار",
    e1077: "میز پر کلاسک انداز بمقابلہ ساتھیوں میں ہلکا پھلکا انداز",
