    e1133: "ڈینش میں شکریہ",
    e1134: "\"Tak\" کے تمام اہم ترین جوابات کا جائزہ لیتی ہے: \"Det var så lidt\"، \"Selv tak\"، \"Så lidt\"، \"Det var ikke noget\"، \"Ingen årsag\"، \"Tak fordi I kunne komme\" اور تعریفوں کے جواب۔",
