    e1144: "\"Tak for i aftes / Tak for i går\" (اگلے دن)، \"Tak for sidst!\" (اگلی ملاقات پر) کے درمیان فرق سمجھاتی ہے – اور یہ کہ کسی ساتھی کو کبھی \"Tak for i nat!\" کیوں نہیں کہنا چاہیے۔",
