    x174: "ہاں... (ظاہر کرتا ہے کہ اب تک کی رہنمائی سمجھ آ گئی ہے)",
    x175: "کیا آپ کو پتہ تھا کہ ہمارے نئے ساتھی پانچ سال اسپین میں رہ چکے ہیں؟",
    x176: "اچھا! مجھے تو بالکل اندازہ نہیں تھا – کتنا دلچسپ ہے!",
    x177: "میں لیٹ ہو گیا کیونکہ پل کے بیچ میں میری سائیکل پنچر ہو گئی تھی۔",
    x178: "اوہ اچھا... تو یہ بات تھی! آہ، کتنی بدقسمتی!",
    x179: "میٹنگ دوسری منزل پر کمرہ 3 میں منتقل ہو گئی ہے۔",
    x180: "آہا، ٹھیک ہے! بتانے کا شکریہ۔",
    x181: "کل میں نے کنسرٹ کے دو مفت ٹکٹ جیتے!",
    x182: "واقعی؟! ارے کتنا زبردست ہے – آپ کسے ساتھ لے جا رہے ہیں؟",
    x183: "انسان کوئی بھی زبان سب سے بہتر تبھی سیکھتا ہے جب روزمرہ زندگی میں اسے بولنے کی ہمت کرے۔",
