    x299: "روبوٹ ڈینش: A: \"گفتگو میں سننا اہم ہے۔\" — B: \"میری بھی یہی رائے ہے۔\"",
    x300: "زندہ ڈینش: A: \"گفتگو میں سننا اہم ہے۔\" — B: \"[1]! یہ [2] بولنے جتنا ہی اہم ہے!\"",
    x301: "معاف کیجیے، کیا میں آپ سے کچھ پوچھ سکتا ہوں؟",
    x302: "معاف کیجیے، کیا میں آپ سے کچھ پوچھ سکتا ہوں؟ کیا آپ جانتے ہیں Aarhus C کی بس کہاں رکتی ہے؟",
    x303: "جی بالکل! وہ بالکل سامنے کونے کے موڑ پر رکتی ہے۔",
    x304: "کیا میں (ذرا) ایک لمحے کے لیے آپ کو زحمت دے سکتا ہوں؟",
    x305: "(ڈیسک پر مسکراتے ہوئے) کیا میں ذرا ایک لمحے کے لیے آپ کو زحمت دے سکتا ہوں؟",
    x306: "جی، بالکل! آپ کیا سوچ رہے ہیں؟",
    x307: "میں براہِ کرم لینا چاہوں گا...",
    x308: "سلام! میں براہِ کرم دو کروسینٹ اور ایک کپ فلٹر کافی لینا چاہوں گا۔",
    x309: "جی بالکل! کیا آپ ساتھ لے کر جائیں گے؟",
    x310: "کیا میں رسید / بل لے سکتا ہوں؟",
    x311: "شکریہ! کیا میں رسید لے سکتا ہوں؟",
    x312: "جی، یہ لیجیے – یہ رہی۔",
    x313: "کیا اتفاقاً آپ کے پاس کوئی... ہوگا، جو میں ادھار لے سکوں؟",
    x314: "کیا اتفاقاً آپ کے پاس کوئی قلم ہوگا، جو میں ادھار لے سکوں؟",
    x315: "جی بالکل، آپ یہاں میز سے نیلا والا لے سکتے ہیں!",
    x316: "کہیں آپ نے میرا چشمہ تو نہیں دیکھا؟",
    x317: "جی ہاں! وہ بالکل آپ کے سامنے میز پر رکھا ہے۔",
    x318: "کیا آپ مہربانی کر کے میری مدد کر دیں گے...؟",
    x319: "کیا آپ مہربانی کر کے ڈینش میں یہ ای میل چیک کرنے میں میری مدد کر دیں گے؟",
    x320: "جی، بالکل! مجھے ذرا دیکھنے دیں۔",
    x321: "میرا بس / ذرا ایک اور سوال ہے",
    x322: "ختم کرنے سے پہلے – میرا بس ذرا ایک اور سوال ہے!",
    x323: "جی، ضرور! بلا جھجھک پوچھیں۔",
    x324: "میں آپ کی کیا مدد کر سکتا ہوں؟ / میں آپ کے لیے کیا کر سکتا ہوں؟",
    x325: "سلام اور خوش آمدید! آج میں آپ کی کیا مدد کر سکتا ہوں؟",
    x326: "سلام! میں براہِ کرم پنیر کے ساتھ دو بن (روٹی) لینا چاہوں گا۔",
    x327: "اگر آپ کو مدد (ایک ہاتھ بٹانے) کی ضرورت ہو تو بس بتا دیجیے گا!",
    x328: "میں ہفتے کو نئے اپارٹمنٹ میں منتقل ہو رہا ہوں۔",
    x329: "زبردست! اگر آپ کو منتقلی میں اضافی مدد کی ضرورت ہو تو بس بتا دیجیے گا!",
    x330: "بس اندر آ جائیں، باہر تو سردی ہے!",
    x331: "(تیز ہوا میں دروازے کی گھنٹی بجاتے ہوئے) سلام!",
    x332: "سلام! بس اندر آ جائیں، باہر تو سردی ہے!",
    x333: "مدد کا بہت بہت شکریہ! (آپ کے وقت / معلومات کا بہت شکریہ)",
    x334: "یہ لیں، میں نے آپ کے لیے رپورٹ کے اعداد و شمار درست کر دیے ہیں۔",
    x335: "مدد کا بہت بہت شکریہ! اس نے واقعی میرا دن بچا لیا۔",
    x336: "کوئی بات نہیں! / آپ کا بھی شکریہ! (تکلف کی کوئی ضرورت نہیں)",
    x337: "بس ڈھونڈنے میں مدد کا بہت شکریہ!",
    x338: "کوئی بات نہیں! Aarhus کا سفر بخیر ہو۔",
    x339: "کھانے کا شکریہ! ↔ نوشِ جان!",
    x340: "کھانے کا شکریہ! یہ واقعی بہت لذیذ تھا۔",
    x341: "نوشِ جان! مجھے بہت خوشی ہے کہ آپ سب کو پسند آیا۔",
    x342: "آج کی شام کا شکریہ! ↔ تشریف آوری کا شکریہ! (آنے کا شکریہ)",
    x343: "مہمان: آج کی شام کا بہت بہت شکریہ! بہت اچھا وقت گزرا۔",
