    x345: "کل شام کا شکریہ! / پچھلی ملاقات کا شکریہ! (کبھی \"کل رات کا شکریہ!\" نہیں)",
    x346: "صبح بخیر! کل شام کا شکریہ (پچھلی ملاقات کا شکریہ)! واقعی بہت مزیدار پارٹی تھی۔",
    x347: "آپ کا بھی شکریہ! ہاں، بے حد خوشگوار تھی۔",
    x348: "ادھار دینے کا شکریہ! / آپ کا بہت شکریہ! (ارے، آپ کتنے اچھے ہیں!)",
    x349: "یہ رہی آپ کی کتاب واپس – ادھار دینے کا بہت بہت شکریہ!",
    x350: "آپ کا بھی شکریہ! امید ہے یہ آپ کے کام آئی ہوگی۔",
    x351: "نہیں شکریہ / پوچھنے کا شکریہ، مزید نہیں! (غیر رسمی: اس بار میں معذرت چاہوں گا!)",
    x352: "کیا آپ ایک اور کپ کافی لیں گے – یا شاید ایک شاپس؟",
